import socket
import json

from taf.sw.reporting_portal.interface import reporting_portal
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.bts_components import Smod
from taf.rfrl.procedures.resources.python.logger import log_result, log_exception
from taf.rfrl.procedures.resources.python.singleton_kpi.SingletonKPI import SingletonKPI
from taf.rfrl.procedures.resources.python.connections import get_ssh_connection_credentials
from taf.rfrl.procedures.resources.python.logger import log_input_and_output


@log_input_and_output
def append_kpi(target, name, value):
    """
    Append KPI results of keyword with provided name to list.

    :param target: Maximum possible target value that keyword might reach.
    :type target: str
    :param name: name of KPI.
    :type name: str
    :param value: Value.
    :type value: str
    """
    SingletonKPI().append_kpi(target, name, value)


def send_report_to_reporting_portal(kpi_tc=False, bts_type='GNB'):
    """
    Keyword to report KPI results which was append to list by append_kpi(target, name, value).
    Reports are sent to Unified Test Environment's Reporting Portal.
    If suite runs KPI test case report will be send also to Quality Center, based on QC config file.

    IMPORTANT:
        This method should be used as the last execution method on Test Suite,
        because after used this method list of KPI will be reset.
    :param kpi_tc: Defines whether suite runs KPI test case.
    :type kpi_tc: Bool
    :param bts_type: type of BTS, can be GNB or ENB
    :type bts_type: str
    """
    ute = reporting_portal()
    if kpi_tc:
        qc_domain, qc_project, qc_test_lab_path, qc_test_set_name = _parse_qc_file()
        link = ute.report_to_rp(
            name=BuiltIn().get_variable_value("${PREV TEST NAME}"),
            result=_check_suite_status(),
            ca="",
            build=_get_sw_version(bts_type=bts_type),
            testline=socket.gethostname().replace("-", "_"),
            tool="Robot",
            label=BuiltIn().get_variable_value("${tl.tl_cloud_topology}"),
            suite_path=BuiltIn().get_variable_value("${SUITE SOURCE}").replace("_temp.robot", ".robot"),
            kpi_results=SingletonKPI().list_of_kpi,
            links={},
            qc_domain=qc_domain,
            qc_project=qc_project,
            qc_testlab_path=qc_test_lab_path,
            qc_test_set_name=qc_test_set_name,
        )

    else:
        link = ute.report_to_rp(
            name="SISO_KPI",
            result="passed",
            ca="",
            build=_get_sw_version(bts_type=bts_type),
            testline=socket.gethostname().replace("7-16-", "5G_Wroclaw_"),
            tool="Robot",
            label=BuiltIn().get_variable_value("${tl.tl_cloud_topology}"),
            suite_path=BuiltIn().get_variable_value("${SUITE_SOURCE}"),
            kpi_results=SingletonKPI().list_of_kpi,
            links={},
        )

    log_result(link)
    SingletonKPI().reset_list_of_kpi()


def _parse_qc_file(qc_domain="MN_5G", qc_project="5G"):
    """
    Parsing qc config file
    :return: qc params that are necessary to qc match
    :rtype tuple
    :raises IOError when can not find qc file
    :raises OSError when can not open qc file
    """
    try:
        with open(_get_qc_file_full_path()) as qc_file:
            data = json.load(qc_file)

            data_vals = data.values()

            if not isinstance(data_vals, list):
                data_vals = list(data_vals)

            for key, val in data_vals[0].items():
                if key == "qc_domain":
                    qc_domain = val
                if key == "qc_project":
                    qc_project = val
                if key.startswith("Root\\"):
                    qc_test_lab_path = key
                    qc_test_set_names = data_vals[0][key].keys()

                    if not isinstance(qc_test_set_names, list):
                        qc_test_set_names = list(qc_test_set_names)

                    qc_test_set_name = qc_test_set_names[0]
            return qc_domain, qc_project, qc_test_lab_path, qc_test_set_name
    except (IOError, OSError):
        log_exception("QC config file not found. QC report will not be available")
        return "", "", "", ""


def _check_suite_status():
    """
    Check if suite passed or failed
    :return: 'passed' or 'failed'
    :rtype str
    """
    return "passed" if BuiltIn().get_variable_value("${SUITE STATUS}") == "PASS" else "failed"


def _get_sw_version(bts_type):
    smod = Smod()
    credentials = get_ssh_connection_credentials(bts_type=bts_type)
    smod.connect_to(address=credentials['host'],
                    username=credentials['username'],
                    password=credentials['password'])
    try:
        return smod.get_sw_version_from_targetbd()
    finally:
        smod.close_connection()


def _get_qc_file_full_path():
    return BuiltIn().get_variable_value("${SUITE SOURCE}").replace("_temp.robot", ".qc")
